import { createMemo, For, Show, type Component, type JSX, type ParentComponent } from "solid-js";
import { render } from "solid-js/web";

import {
	DragAndDrop,
	DragDropCallback,
	DragDropPredicate,
	DragEndCallback,
	DragEndStatus,
	Draggable,
	Dropzone,
	useDragAndDropContext,
	useDraggableContext,
	useDropzoneContext,
	type DraggableProps,
} from "#core/ui-next/components/drag-and-drop.jsx";
import { Header } from "#core/ui-next/components/header.jsx";
import { useInventoryModel } from "#core/ui-next/reference/drag-and-drop/inventory-model.js";

export interface TileProps {
	style?: JSX.CSSProperties;
	value?: string;
}
export const Tile = (props: TileProps) => {
	return (
		<div class="tile" style={props.style}>{props.value ?? "?"}</div>
	)
}

interface NamedContainerProps {
	caption: string;
	children?: JSX.Element;
}

const NamedContainer: ParentComponent<NamedContainerProps> = (props) => {

	const dndContext = useDragAndDropContext();
	const dzContext = useDropzoneContext();

	const extraClasses = createMemo(() => {

		const dz = dzContext.dropzone();
		if (dz && dndContext.isDragging()) {
			if (dzContext.canDrop()) {
				const overDZ = dndContext.overDropzone();
				if (overDZ && overDZ.dropzone.id == dz.id) {
					return "items-can-drop-hover cursor-pointer";
				}
				else {
					return "items-can-drop cursor-pointer"
				}
			}
			else {
				return "items-no-drop cursor-not-allowed";
			}

		}

		return "";
	})

	return (
		<div class={`relative flex flex-row flex-wrap justify-around items-center items ${extraClasses()}`}>
			<div class="absolute top-0 left-2 font-body text-xl">{props.caption}</div>
			{props.children}
		</div>
	);
}

interface EmptySlotProps {
	caption: string;
}

const EmptySlot: ParentComponent<EmptySlotProps> = (props) => {

	const dndContext = useDragAndDropContext();
	const dzContext = useDropzoneContext();
	const extraClasses = createMemo(() => {

		const dz = dzContext.dropzone();
		if (dz && dndContext.isDragging()) {
			if (dzContext.canDrop()) {
				const overDZ = dndContext.overDropzone();
				if (overDZ && overDZ.dropzone.id == dz.id) {
					return "slot-can-drop-hover cursor-pointer";
				}
				else {
					return "slot-can-drop cursor-pointer"
				}
			}
			else {
				return "slot-no-drop cursor-not-allowed";
			}

		}

		return "";
	})

	return (<div class={`slot ${extraClasses()}`}>{props.caption}</div>);
}

interface DraggableTileProps {
	value: string;
}
const DraggableTile: Component<DraggableTileProps> = (props) => {

	const dragonDropContext = useDragAndDropContext();
	const context = useDraggableContext();
	const dzContext = useDropzoneContext();


	const tileOpacity = createMemo(() => {
		if (!context.isRenderingOverlay && dragonDropContext.isDragging() != null) {
			if (dzContext.dropzone() == null || !dzContext.canDrop()) {
				return "0.5";
			}
		}

		return "";
	});

	const cursor = createMemo(() => {
		if (!context.isRenderingOverlay && dragonDropContext.isDragging() != null) {
			if (dzContext.dropzone() != null && dzContext.canDrop()) {
				return "pointer";
			}
		}
		else {
			return "";
		}
	})

	const slotting = createMemo(() => {
		if (context.isRenderingOverlay) {
			const dz = dragonDropContext.overDropzone();
			if (dz && dz.canDrop()) {
				if (["Slot1", "Slot2", "Slot3"].includes(dz.dropzone.data as string)) {
					return true;
				}
			}
		}

		return false;
	})

	return (
		<div class="flex flex-col justify-center items-center">
			<Tile value={props.value} style={{
				opacity: tileOpacity(),
				cursor: cursor()
			}} />
			<Show when={slotting()}>
				<div style={{ "background-color": "white", color: "black" }}>This will unequip any existing item in this slot.</div>
			</Show>
		</div>
	)
}

interface InventoryItemProps extends DraggableProps {
	value: string;
}
const InventoryItem: Component<InventoryItemProps> = (props) => {
	return (
		<Draggable data={props.value} onDragStart={props.onDragStart} onDragEnd={props.onDragEnd} onDragDrop={props.onDragDrop} canDrop={props.canDrop}>
			<DraggableTile value={props.value} />
		</Draggable>
	);
}

const App: Component = () => {

	const inventory = useInventoryModel();

	const handleDragDrop: DragDropCallback = (draggable, dropzone) => {

		const dragged = draggable.data as string;

		// Do nothing if this is the regional zone.
		if (dropzone.data == "Regional") {
			inventory.autoSlotItem(dragged);
			return;
		}

		inventory.equipItem(dragged, dropzone.data as string);
	}

	const handleEquipmentDragEnd: DragEndCallback = (draggable, status, _zone, _position) => {
		if (status == DragEndStatus.Released) {
			inventory.unEquipItem(draggable.data as string);
		}
	}

	const canEquipItem: DragDropPredicate = (draggable, dropzone) => {
		const memo = createMemo(() => {
			const item = (typeof (draggable.data) == 'string') ? draggable.data : '';
			const slot = (typeof (dropzone.data) == 'string') ? dropzone.data : '';

			return (item != '' && slot != '') ? inventory.canContain(item, slot) : false;
		});
		return memo;
	};

	const canDropIntoAutoEquip: DragDropPredicate = (draggable, _dropzone) => {
		const memo = createMemo(() => {
			const item = (typeof (draggable.data) == 'string') ? draggable.data : '';
			return (item != '') ? inventory.canAutoSlotItem(item) : false;
		});
		return memo;
	};

	const extrasCaption = createMemo(() => {
		const extras = inventory.state.containers.find(c => c.id == "Extras");

		return `Extras ${inventory.items("Extras").length}/${extras?.maxCount}`;
	});

	return (
		<div class="absolute inset-0 flex flex-col">
			<Header class="ml-3 mt-2 mb-2">Drag and Drop Inventory Example</Header>
			<div class="font-body text-lg ml-3 mt-2 mb-2 text-tertiary-1">Items can be placed in either bag.  Only letters may be equipped in slots while Extras accepts up to 3 items of either type.</div>
			<div class="flex flex-row flex-auto"
				style={{
					"background-color": "grey",
				}}
			>
				<DragAndDrop
					onDragDrop={handleDragDrop}
					debugTrace={true}
				>
					<div class="flex flex-col flex-auto" style={{ "max-width": "50%" }}>
						<Dropzone debugId="Bag1 Dropzone" data="Bag1">
							<NamedContainer caption={"Container 1"}>
								<For each={inventory.items("Bag1")}>
									{(item) => (
										<InventoryItem value={item} />
									)}
								</For>
							</NamedContainer>
						</Dropzone>
						<Dropzone debugId="Bag2 Dropzone" data="Bag2">
							<NamedContainer caption="Container 2">
								<For each={inventory.items("Bag2")}>
									{(item) => (
										<InventoryItem value={item} />
									)}
								</For>
							</NamedContainer>
						</Dropzone>
					</div>
					<div class="flex flex-col" style={{ "flex": "2 1 auto" }}>
						<Dropzone debugId="Regional Dropzone" data="Regional" canDrop={canDropIntoAutoEquip}>
							<NamedContainer caption="Gear">
								<For each={["Slot1", "Slot2", "Slot3"]}>
									{(slot) => (
										<Dropzone debugId="Nested Dropzone" data={slot} canDrop={canEquipItem}>
											<Show when={inventory.items(slot).length > 0} fallback={<EmptySlot caption={slot} />}>
												<InventoryItem value={inventory.items(slot)[0]} onDragEnd={handleEquipmentDragEnd} />
											</Show>
										</Dropzone>)
									}
								</For>
							</NamedContainer>
						</Dropzone>

						<Dropzone debugId="Extras Dropzone" data="Extras" canDrop={canEquipItem}>
							<NamedContainer caption={extrasCaption()}>
								<For each={inventory.items("Extras")}>
									{(item) => (
										<InventoryItem value={item} onDragEnd={handleEquipmentDragEnd} />
									)}
								</For>
							</NamedContainer>
						</Dropzone>
					</div>
				</DragAndDrop>
			</div>
		</div>
	);
};

engine.whenReady.then(() => {
	render(() => {
		return (
			<App />
		);
	}, document.getElementById("root")!);
});
